import {raidEnemies} from './raid-hud.js';
import {C2_REGIONS} from './chapter-two-world.js';
import {C3_REGIONS} from './chapter-three-scenery.js';
export const MAP_REGIONS={forest:{name:'Темнолесье',bounds:[-42,-124,84,140]},deep:{name:'Глубины Темнолесья',bounds:[180,-204,120,170]},cemetery:{name:'Кладбище Темнолесья',bounds:[-400,-205,140,170]},chapel:{name:'Затопленная часовня',bounds:[950,-175,100,112]},dungeon:{name:'Склеп',bounds:[455,-163,65,107]},lich:{name:'Зал Лича',bounds:[674,-151,52,62]},home:{name:'Дом Альфреда',bounds:[59,-102,12,13]},hut:{name:'Дом ведьмы',bounds:[101,-114,38,35]},trial:{name:'Испытание тени',bounds:[104,-322,32,48]},admin:{name:'Испытательная комната',bounds:[674,-151,52,62]}};
for(const [id,r] of Object.entries(C2_REGIONS))MAP_REGIONS['c2_'+id]={name:r.name,bounds:[r.x-r.w/2,-r.h,r.w,r.h]};for(const [id,r] of Object.entries(C3_REGIONS))MAP_REGIONS['c3_'+id]={name:r.name,bounds:[r.x-r.w/2,-r.h,r.w,r.h]};
export function mapLinks(zone,p={}){const cityNorth=['chapter_three','chapter_four'].includes(p.stage)?'c3_pass':p.manorShortcut?'c2_manor':'c2_inn';const links={forest:[[35,-100,'deep'],[-35,-100,'cemetery'],[0,-118,'c2_road']],deep:[[240,-45,'forest'],[292,-184,'hut']],cemetery:[[-330,-43,'forest'],[-330,-109,'dungeon'],[-330,-189,'chapel']],chapel:[[1000,-71,'cemetery']],dungeon:[[480,-60,'cemetery'],[480,-156,'lich']],lich:[[700,-96,'dungeon']],home:[[65,-91,'forest']],hut:[[120,-95,'deep']],c2_road:[[2000,-18,'forest'],[2000,-234,'c2_city']],c2_city:[[2400,-20,'c2_road'],[2400,-224,cityNorth]],c2_inn:[[2800,-18,'c2_city'],[2800,-181,'c2_manor']],c2_manor:[[3200,-18,'c2_city']],c3_pass:[[3600,-20,'c2_city'],[3600,-258,'c3_fortress']],c3_fortress:[[4000,-20,'c3_pass'],[4000,-207,'c3_quarry'],[4076,-170,'c3_marsh'],[4006,-77,'c3_siege']],c3_quarry:[[4400,-26,'c3_fortress']],c3_siege:[[4800,-20,'c3_fortress']],c3_marsh:[[5200,-20,'c3_fortress'],[5200,-304,'c3_abbey']],c3_abbey:[[5600,-20,'c3_marsh'],[5600,-278,'c3_aerie']],c3_aerie:[[6000,-20,'c3_abbey']]};return (links[zone]||[]).map(([x,z,to])=>({x,z,to,name:MAP_REGIONS[to].name}))}
export function waypointDirection(zone,pin,p){if(!pin||!MAP_REGIONS[pin.zone])return null;if(pin.zone===zone)return [pin.x,pin.z];const queue=[{zone,first:null}],seen=new Set([zone]);for(let i=0;i<queue.length;i++)for(const link of mapLinks(queue[i].zone,p)){if(seen.has(link.to))continue;const first=queue[i].first||[link.x,link.z];if(link.to===pin.zone)return first;seen.add(link.to);queue.push({zone:link.to,first})}return null}
export function validMapPin(pin){if(pin===null||pin===undefined)return true;const r=MAP_REGIONS[pin.zone];return !!r&&Number.isFinite(pin.x)&&Number.isFinite(pin.z)&&pin.x>=r.bounds[0]&&pin.x<=r.bounds[0]+r.bounds[2]&&pin.z>=r.bounds[1]&&pin.z<=r.bounds[1]+r.bounds[3]}
export function reachedPin(zone,pin,pos){return !!pin&&zone===pin.zone&&Math.hypot(pos.x-pin.x,pos.z-pin.z)<4}
export function mapDescription(ctx,zone,current){const def=MAP_REGIONS[zone]||MAP_REGIONS.forest;let actual={};if(zone.startsWith('c3_'))actual=ctx.chapterThree?.map?.(zone.slice(3))||{};else if(zone.startsWith('c2_'))actual=(ctx.chapterTwo?.legacy||ctx.chapterTwo)?.map?.(zone.slice(3))||{};else if(zone===current){const area=ctx.chapterTwo?.inside?ctx.chapterTwo:ctx.admin?.inside?ctx.admin:ctx.chapel?.inside?ctx.chapel:ctx.dungeon?.inside?ctx.dungeon:ctx.ritual?.inside?ctx.ritual:null;actual=area?.map?.()||{}}
 const [x,z,w,h]=def.bounds,buildings=[...(actual.buildings||[])],floors=[...(actual.floors||[])],markers=(actual.markers||[]).filter(m=>!m[2]?.includes('a582')&&!m[2]?.includes('b58'));
 if(!buildings.length){if(zone==='c2_city'){for(const xx of [-81,-33,33,81])for(const zz of [-52,-88,-158,-194])buildings.push([2400+xx-5,zz-6.5,10,13]);for(const side of [-1,1])for(const zz of [-66,-88,-163,-194])buildings.push([2400+side*17-5,zz-7,10,14]);}if(zone==='c2_city')for(const [xx,zz,name] of [[2353,-154,'Кузница'],[2455,-105,'Травник'],[2345,-132,'Алхимик'],[2446,-154,'Повар'],[2455,-174,'Кожевник']]){buildings.push([xx-6,zz-7,12,14]);markers.push([xx,zz,'#d6b97b',name])}if(zone==='c3_fortress'){buildings.push([3976,-191,48,32]);for(const side of [-1,1]){for(const z of [-65,-113])buildings.push([4000+side*63-9,z-11,18,22]);buildings.push([4000+side*50-7.5,-146,15,14]);}markers.push([4045,-106,'#d6b97b','Оружейная'],[3957,-97,'#d6b97b','Интендант'],[3980,-91,'#a0d8e4','Наставник'])}if(zone==='c3_abbey')buildings.push([5554,-260,92,84]);if(zone==='forest'){for(const b of ctx.mapData?.buildings||[])if(b.x<42)buildings.push([b.x-4,b.z-4,8,8])}}
 if(!floors.length)floors.push([x+w/2-4,z+12,8,h-24]);const islands=[...(actual.islands||[])];if(zone==='c3_marsh'&&!islands.length)for(const [px,pz,r] of [[0,-45,29],[0,-105,33],[-48,-115,26],[48,-170,29],[0,-185,36],[-46,-235,28],[0,-280,32]])islands.push({x:5200+px,z:pz,r});
 if(zone==='c2_city')for(const n of raidEnemies(ctx.chapterTwo?.legacy||ctx.chapterTwo))markers.push([n.g.position.x,n.g.position.z,'#ff4545']);const trees=actual.trees?.length?actual.trees:(ctx.mapData?.blockers||[]).filter(b=>b.x>=x&&b.x<x+w&&b.z>=z&&b.z<z+h).map(b=>[b.x,b.z,b.r]);if(!trees.length&&['forest','deep','c2_road','c2_inn','c2_manor','c3_pass','c3_abbey'].includes(zone))for(let i=0;i<130;i++){const tx=x+((i*47.31)%w),tz=z+((i*79.17)%h);if(Math.abs(tx-(x+w/2))>10&&!buildings.some(([bx,bz,bw,bh])=>tx>bx-3&&tx<bx+bw+3&&tz>bz-3&&tz<bz+bh+3))trees.push([tx,tz,1.5+i%3*.3]);}return {...def,...actual,bounds:def.bounds,buildings,floors,markers:markers.filter((m,i,a)=>a.findIndex(v=>v[0]===m[0]&&v[1]===m[1]&&v[3]===m[3])===i),islands,trees};
}
